// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address anyCaller, address newDistributor) public {
        // Ensure calls don't revert unexpectedly
        vm.assume(anyCaller != address(0));

        address ownerBefore = c.owner();

        // Call a function that requires onlyOwner but will revert if caller is not owner
        // We'll call setRewardDistributor with anyCaller to trigger the revert case
        vm.prank(anyCaller);
        (bool success, ) = address(c).call(
            abi.encodeWithSelector(c.setRewardDistributor.selector, newDistributor)
        );

        address ownerAfter = c.owner();

        // The rule: owner() never changes regardless of successful or failed calls
        assertTrue(ownerBefore == ownerAfter, "Owner should remain constant");
    }
}

