contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address staker, address rewardToken, uint256 rewardAmount) public {
        vm.assume(rewardToken != address(0) && staker != address(0));
        vm.assume(rewardAmount < 100_000_000 ether);

        // Deploy a token and fund this contract with tokens to become reward distributor
        // For simplicity, use address(this) as the reward token (non-ERC20, but will pass the address check)
        // Actually, we need a valid ERC20 to call addReward and notifyRewardAmount
        // Deploy a minimal ERC20 for testing
        // Since we cannot deploy other contracts, we will assume staker is a contract that responds
        // We'll just call addReward with a specific token address that we control via vm

        // Instead, we use a pre-funded ERC20 mock deployed in setUp
        // For Foundry, we can use address(this) as token and send it tokens
        // Simpler: just test that addReward does not change claimableRewards for any address

        // First, stake some tokens for the staker to have balance
        // Deploy a simple ERC20 for staking token
        // Actually, the constructor requires _stakingToken, but we passed address(this) which is fine
        // We'll send staking tokens to the test contract so it can approve

        // For simplicity, we test with a random reward token and ensure claimableRewards remains zero
        // The rule: for any staker and rewardToken, after addReward, claimableRewards[staker][rewardToken] remains unchanged (specifically zero if never set)

        uint256 before = c.claimableRewards(staker, rewardToken);

