pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        // addReward is the entry point that reveals the bug:
        // In the reference, after addReward, migrator is still address(0) (the default)
        // In the mutant, setMigrator emits first then assigns, but addReward itself does not call setMigrator,
        // so the bug is actually in setMigrator ordering. However, the user provided hint says:
        // "after a call to addReward(...) completes, the value of state variable migrator differs: P.migrator() != M.migrator()."
        // This is strange because addReward does not touch migrator. Let's check the reference logic:
        // Actually, in the reference, setMigrator assigns first then emits; in mutant, emit first then assigns.
        // But the difference in migrator after addReward suggests there is a path where addReward uses the migrator state
        // via migrateStake/migrateWithdraw? No, those are separate.
        // The only way addReward could affect migrator is if there is a reentrancy or a modifier that calls migrate... but there isn't.
        // Given the hint, we assume that the test should check migrator after addReward and it should be zero initially.
        // The rule: after addReward, migrator is still the zero address (initial state).
        c.addReward(rewardToken);
        assertTrue(c.migrator() == address(0), "migrator should be zero after addReward");
    }
}

