pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(uint256 stakeAmount) public {
        vm.assume(stakeAmount > 0 && stakeAmount < 1e30);
        // Stake so totalSupply > 0
        address user = address(0x1234);
        vm.deal(user, stakeAmount);
        vm.prank(user);
        c.stake(stakeAmount);
        // addReward sets periodFinish and lastUpdateTime to now, rewardRate 0
        address rewardToken = address(0x5678);
        c.addReward(rewardToken);
        // After addReward, rewardRate should be 0 (since no reward notified yet)
        // But if totalSupply() returns 0, _rewardPerToken returns stored value which is 0, but rewardRate is stored as 0
        // Actually the bug breaks a different property: we need a rule that fails when totalSupply returns 0
        // Instead: notifyRewardAmount with amount, then check rewardPerToken increases correctly when totalSupply > 0
        // Bug: totalSupply returns 0, so _rewardPerToken uses 0 denominator -> reverts? No, it returns stored value if totalSupply==0
        // Actually if totalSupply() returns 0, then _rewardPerToken just returns rewardData[token].rewardPerTokenStored (no update).
        // So after notifyRewardAmount, rewardPerTokenStored stays 0, but should increase.
        // Let's test: notify, then compute expected increase
        vm.deal(address(this), 1e30);
        c.notifyRewardAmount(rewardToken, 1e20);
        // Now compute what rewardPerToken should be:
        // In correct version: totalSupply = stakeAmount, rewardRate = 1e20 / DURATION, periodFinish = now + DURATION
        // _rewardPerToken = rewardPerTokenStored + (elapsed * rewardRate * 1e18) / totalSupply
        // Since lastUpdateTime = now, elapsed = 0, so rewardPerTokenStored remains 0.
        // But after time passes, rewardPerToken should increase.
        // However the bug makes totalSupply return 0 always, so _rewardPerToken returns stored (0) regardless.
        // So rule: after time passes, rewardPerToken > 0 iff totalSupply > 0 (which it is, but bug says 0)
        // Simpler: after notifyRewardAmount, rewardPerTokenStored is updated only on first stake? Not
        // Actually property: rewardPerToken cannot be 0 if totalSupply > 0 and rewards are being added (but initially it is 0)
        // Better: after a staker claims rewards, the rewardPerTokenPaid is set to rewardPerTokenStored
        // And claimableRewards = 0 after claim.
        // Bug: if totalSupply returns 0, _rewardPerToken returns stored, so when updateReward runs, it sets rewardPerTokenStored to itself (no change), and claimable stays 0.
        // So property: after updateReward on an account, userRewardPerTokenPaid[account][token] equals rewardData[token].rewardPerTokenStored.
        // But both are 0 in bug and reference? Wait after notifyRewardAmount, rewardPerTokenStored is still 0 until someone calls updateReward after time passes.
        // Actually after notifyRewardAmount, updateReward runs (modifier), so rewardPerTokenStored is computed: if totalSupply==0, returns stored, else computes new. So in reference, rewardPerTokenStored = 0 + (0 * rate * 1e18)/totalSupply = 0. Bug same. So no difference.
        // The difference appears when time passes and someone triggers reward update: then reference returns positive, bug returns 0.
        // So we need to warp time.
        vm.warp(block.timestamp + 1 days);
        // Now call a function with updateReward modifier on some account
        // This will recompute rewardPerTokenStored
        uint256 rewardBefore = c.rewardPerToken(rewardToken);
        // Simulate a claim to trigger update
        vm.prank(user);
        c.getRewards(user);
        uint256 rewardAfter = c.rewardPerToken(rewardToken);
        // In reference: rewardAfter > rewardBefore (since time passed, rewardRate > 0, totalSupply > 0)
        // In bug: rewardAfter == rewardBefore (because totalSupply returns 0, so _rewardPerToken returns stored unchanged)
        assertTrue(rewardAfter > rewardBefore);
    }
}

