pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }
    function testFuzz_property(address rewardToken) public {
        vm.assume(rewardToken != address(0));
        vm.assume(rewardToken != address(c));

        // Add the reward token
        c.addReward(rewardToken);

        // Read the stored rewardPerTokenStored and periodFinish
        // Since rewardData is public, we can read it via the auto-generated getter
        // But rewardData is a struct mapping, so we need to read the individual fields
        // The struct Reward has fields: periodFinish, rewardRate, lastUpdateTime, rewardPerTokenStored
        (uint40 periodFinish, uint216 rewardRate, uint40 lastUpdateTime, uint216 rewardPerTokenStored) = c.rewardData(rewardToken);

        // The reward per token should be at most rewardPerTokenStored + (rewardRate * (periodFinish - lastUpdateTime) * 1e18 / totalSupply) when totalSupply > 0
        // But if totalSupply is 0, it should equal rewardPerTokenStored
        uint256 totalSupply = c.totalSupply();
        uint256 rewardPerTokenActual = c.rewardPerToken(rewardToken);

        if (totalSupply == 0) {
            assertTrue(rewardPerTokenActual == rewardPerTokenStored, "rewardPerToken should equal stored when totalSupply is 0");
        } else {
            // Since we just added the reward, periodFinish = block.timestamp + DURATION, lastUpdateTime = block.timestamp
            // So periodFinish - lastUpdateTime = DURATION
            // rewardRate was set to 0 because no reward was notified yet, so rewardRate is 0
            // Therefore rewardPerToken should equal rewardPerTokenStored
            assertTrue(rewardPerTokenActual >= rewardPerTokenStored, "rewardPerToken should be at least stored value");

            // Maximum possible increase
            // Since no reward has been notified, rewardRate is 0 so the increase is 0
            uint256 maxIncrease = (uint256(rewardRate) * (uint256(periodFinish) - uint256(lastUpdateTime)) * 1e18) / totalSupply;
            assertTrue(rewardPerTokenActual <= rewardPerTokenStored + maxIncrease, "rewardPerToken should not exceed stored plus max increase");
        }
    }
}

