pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    function testFuzz_property(address account, uint256 stakeAmount, uint256 rewardAmount) public {
        // Bound inputs to avoid overflow
        stakeAmount = bound(stakeAmount, 1, 1e30);
        rewardAmount = bound(rewardAmount, 1, 1e30);

        // Setup: add a reward token, notify some reward, and stake from the account
        // Use a dummy reward token (this contract itself) for simplicity
        address rewardToken = address(this);
        c.addReward(rewardToken);

        // Fund the reward distributor (this contract) with reward tokens
        deal(rewardToken, address(this), rewardAmount);
        IERC20(rewardToken).approve(address(c), rewardAmount);

        // Notify reward amount
        c.notifyRewardAmount(rewardToken, rewardAmount);

        // Give staking tokens to the account (this contract) and stake
        deal(address(c.stakingToken()), account, stakeAmount);
        vm.prank(account);
        IERC20(address(c.stakingToken())).approve(address(c), stakeAmount);

        vm.prank(account);
        c.stake(stakeAmount);

        // Advance time so rewards accumulate (fast-forward to just before period end)
        vm.warp(block.timestamp + 1000);

        // Get the earned value for the account with actual balance
        uint256 earnedWithBalance = c.earned(account, rewardToken);

        // Now simulate a change in balance: withdraw all so balance becomes 0
        vm.prank(account);
        c.withdrawAll(false);

        // Get earned value after balance is 0
        uint256 earnedAfterWithdraw = c.earned(account, rewardToken);

        // The two earned values should be different because the balance changed
        // The bug makes earned always use 0 balance, so they would be equal
        assertTrue(earnedWithBalance != earnedAfterWithdraw, "earned should depend on balance");
    }
}

