        c.stake(amount);

        // Add reward token
        c.addReward(rewardToken);

        // Verify that after adding the reward token, the user's claimable reward for it is 0
        // This is the invariant: new reward tokens should not have pending rewards immediately after being added
        bool invariantHolds = c.claimableRewards(staker, rewardToken) == 0;
        assertTrue(invariantHolds);
    }
}

